#include "top_sub_C_sub_c.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void top_sub_C_sub_c_initialize(void);
void top_sub_C_sub_c_notify(microkit_channel channel);
void top_sub_C_sub_c_timeTriggered(void);

volatile sb_queue_int32_t_1_t *Input1_queue_1;
sb_queue_int32_t_1_Recv_t Input1_recv_queue;
volatile sb_queue_int32_t_1_t *Input2_queue_1;
sb_queue_int32_t_1_Recv_t Input2_recv_queue;
volatile sb_queue_int32_t_1_t *Output_queue_1;

#define PORT_FROM_MON 0

int32_t last_Input1_payload;

bool get_Input1(int32_t *data) {
  sb_event_counter_t numDropped;
  int32_t fresh_data;
  bool isFresh = sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &Input1_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_Input1_payload = fresh_data;
  }
  *data = last_Input1_payload;
  return isFresh;
}

int32_t last_Input2_payload;

bool get_Input2(int32_t *data) {
  sb_event_counter_t numDropped;
  int32_t fresh_data;
  bool isFresh = sb_queue_int32_t_1_dequeue((sb_queue_int32_t_1_Recv_t *) &Input2_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_Input2_payload = fresh_data;
  }
  *data = last_Input2_payload;
  return isFresh;
}

bool put_Output(const int32_t *data) {
  sb_queue_int32_t_1_enqueue((sb_queue_int32_t_1_t *) Output_queue_1, (int32_t *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_int32_t_1_Recv_init(&Input1_recv_queue, (sb_queue_int32_t_1_t *) Input1_queue_1);

  sb_queue_int32_t_1_Recv_init(&Input2_recv_queue, (sb_queue_int32_t_1_t *) Input2_queue_1);

  sb_queue_int32_t_1_init((sb_queue_int32_t_1_t *) Output_queue_1);

  top_sub_C_sub_c_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      top_sub_C_sub_c_timeTriggered();
      break;
    default:
      top_sub_C_sub_c_notify(channel);
  }
}
